export function validateConfig(config) {
  if (!config.auth.token) {
    throw new Error('GET_NOTE_API_KEY environment variable is required');
  }
  
  if (!config.api.baseURL) {
    throw new Error('API base URL is required');
  }
  
  if (config.api.timeout <= 0) {
    throw new Error('API timeout must be positive');
  }
  
  if (config.api.retries < 0) {
    throw new Error('API retries must be non-negative');
  }
  
  // 警告但不强制要求topic_id
  if (!config.knowledgeBase.topicId) {
    console.warn('⚠️  GET_NOTE_TOPIC_ID not set. You will need to provide topic_id in tool calls.');
  }
  
  return true;
}